{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C19"],
      "claim": "Artemisinin, the closest experimental analogue (Morgan 0.178) and a polycyclic lactone natural product, is reported to have low oral bioavailability in humans, supporting a low-F prediction for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C18"],
      "claim": "Artesunate, an artemisinin derivative, showed 61% absolute oral bioavailability in Thai patients; this is contradictory to a low-F prediction but has very limited transferability because the query lacks the endoperoxide and is far more polar.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C12"],
      "claim": "Doxifluridine, a nucleoside analogue, reached ~80% oral bioavailability in patients, providing weak contradictory evidence; its structural similarity to the query is very low (Morgan 0.153).",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "low",
  "decision_summary": "The query is a highly polar, rigid polycyclic lactone (logD -2.4, PSA 169 Å², 11 HBA) with physicochemical properties predicting poor passive permeability and low oral bioavailability. The closest experimental analogue, artemisinin, also a polycyclic lactone, shows low/poor oral bioavailability in humans. Other analogues with higher F values are structurally very distant (Morgan similarity <0.16) and do not override the coherent low-F prior and artemisinin evidence. Prediction: low.",
  "evidence_gaps": [
    "No direct experimental oral bioavailability data for the query molecule.",
    "All experimental analogues have very low Morgan similarity (<0.18), limiting transferability.",
    "No permeability, transporter, or metabolism data specific to the query are available.",
    "The physicochemical prior is computational and not a substitute for experimental evidence."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

